  function loadState() {
    try { const raw = localStorage.getItem(STORE_KEY); return raw ? { ...defaultState, ...JSON.parse(raw) } : structuredClone(defaultState); }
    catch { return structuredClone(defaultState); }
  }
  function persist() { state.updatedAt = new Date().toISOString(); try { localStorage.setItem(STORE_KEY, JSON.stringify(state)); } catch (e) { toast('تعذر حفظ البيانات محلياً. نزّل نسخة احتياطية أو احذف بعض البيانات.'); } updateStats(); }
  function t(key) { return (strings[language] && strings[language][key]) || strings.ar[key] || key; }
  function toast(message) { const el = $('toast'); if (!el) return; el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 3100); }
  function setMessage(id, text, isError=false) { const el=$(id); if (!el) return; el.textContent=text; el.classList.toggle('error', Boolean(isError)); }

  // IndexedDB keeps original files outside localStorage's small text quota.
  function openMediaDB() {
    return new Promise((resolve, reject) => {
      if (!('indexedDB' in window)) return reject(new Error('IndexedDB is not available'));
      const request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = () => { const db = request.result; if (!db.objectStoreNames.contains(DB_STORE)) db.createObjectStore(DB_STORE, { keyPath: 'id' }); };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error || new Error('Database open failed'));
    });
  }
  async function putMedia(id, file) {
    const db = await openMediaDB();
    return new Promise((resolve, reject) => { const tx=db.transaction(DB_STORE,'readwrite'); tx.objectStore(DB_STORE).put({id, blob:file, name:file.name, type:file.type, size:file.size, savedAt:new Date().toISOString()}); tx.oncomplete=()=>{db.close();resolve(true)}; tx.onerror=()=>{db.close();reject(tx.error)}; });
  }
  async function getMedia(id) {
    const db = await openMediaDB();
    return new Promise((resolve, reject) => { const tx=db.transaction(DB_STORE,'readonly'); const req=tx.objectStore(DB_STORE).get(id); req.onsuccess=()=>{db.close();resolve(req.result || null)}; req.onerror=()=>{db.close();reject(req.error)}; });
  }
  async function deleteMedia(id) {
    try { const db=await openMediaDB(); await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close(); } catch {}
    const url=blobUrls.get(id); if(url){URL.revokeObjectURL(url);blobUrls.delete(id)}
  }
  async function getMediaUrl(id) {
    if (blobUrls.has(id)) return blobUrls.get(id);
    const item = await getMedia(id); if (!item?.blob) return null;
    const url=URL.createObjectURL(item.blob); blobUrls.set(id,url); return url;
  }
  function initSupabase() {
    const cfg=window.STUDIO_CONFIG||{};
    if(!cfg.supabaseUrl||!cfg.supabaseAnonKey||!window.supabase?.createClient){supabaseClient=null;setConnection(false);return;}
    try { supabaseClient=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}); setConnection(false); supabaseClient.auth.getSession().then(({data})=>{currentUser=data?.session?.user||null;syncBadge();if(currentUser)loadCloudData().catch(()=>{});}); supabaseClient.auth.onAuthStateChange((_event,session)=>{currentUser=session?.user||null;syncBadge();if(currentUser)loadCloudData().catch(()=>{});}); }
    catch { supabaseClient=null;setConnection(false); }
  }
  function setConnection(connected) {
    const el=$('connectionState'); if(!el)return;
    const dot=el.querySelector('.state-dot'); if(dot)dot.classList.toggle('offline',!connected);
    const span=el.querySelector('span:last-child'); if(span)span.textContent=connected?t('cloudMode'):t('localMode');
  }
  function syncBadge(){setConnection(Boolean(currentUser&&supabaseClient));$('signOut')?.classList.toggle('hidden',!currentUser);if(currentUser){$('authEmail').value=currentUser.email||'';setMessage('authMessage',`${currentUser.email||''} · ${t('synced')}`)} }
  async function authCall(kind) {
    if(!supabaseClient){setMessage('authMessage',t('needSetup'),true);return;}
    const email=$('authEmail').value.trim(),password=$('authPassword').value;
    if(!email||!password){setMessage('authMessage',t('nameRequired'),true);return;}
    try{
      let result;
      if(kind==='signup') result=await supabaseClient.auth.signUp({email,password}); else result=await supabaseClient.auth.signInWithPassword({email,password});
      if(result.error)throw result.error;
      if(kind==='signup'){setMessage('authMessage',t('accountCreated'));} else {currentUser=result.data.user||result.data.session?.user||null;syncBadge();setMessage('authMessage',t('signedIn'));await loadCloudData();}
    }catch(e){setMessage('authMessage',e.message||String(e),true);}
  }
  async function loadCloudData() {
    if(!supabaseClient||!currentUser)return;
    try{
      const [pRes,cRes,eRes,sRes,aRes,jRes]=await Promise.all([
        supabaseClient.from('projects').select('*').order('updated_at',{ascending:false}),
        supabaseClient.from('characters').select('*').order('created_at',{ascending:false}),
        supabaseClient.from('episodes').select('*').order('episode_number',{ascending:true}),
        supabaseClient.from('scenes').select('*').order('scene_number',{ascending:true}),
        supabaseClient.from('media_assets').select('*').order('created_at',{ascending:false}),
        supabaseClient.from('generation_jobs').select('*').order('created_at',{ascending:false})
      ]);
      [pRes,cRes,eRes,sRes,aRes,jRes].forEach(r=>{if(r.error)throw r.error});
      const localProjects=state.projects; const cloudProjects=(pRes.data||[]).map(p=>({id:p.id,title:p.title,description:p.description||'',type:p.project_type||'series',status:p.status||'planning',createdAt:p.created_at,updatedAt:p.updated_at,episodes:[]}));
      const projectMap=new Map([...localProjects.map(p=>[p.id,p]),...cloudProjects.map(p=>[p.id,{...(localProjects.find(x=>x.id===p.id)||{}),...p,episodes:(localProjects.find(x=>x.id===p.id)?.episodes||[])}])]);
      state.projects=[...projectMap.values()];
      const episodeRows=eRes.data||[],sceneRows=sRes.data||[];
      for(const e of episodeRows){const project=state.projects.find(p=>p.id===e.project_id);if(!project)continue;project.episodes=project.episodes||[];let epi=project.episodes.find(x=>x.id===e.id);if(!epi){epi={id:e.id,number:e.episode_number,title:e.title,synopsis:e.synopsis||'',scenes:[]};project.episodes.push(epi)}else Object.assign(epi,{number:e.episode_number,title:e.title,synopsis:e.synopsis||''});}
      for(const s of sceneRows){for(const project of state.projects){for(const e of project.episodes||[]){if(e.id===s.episode_id){e.scenes=e.scenes||[];let sc=e.scenes.find(x=>x.id===s.id);if(!sc)e.scenes.push({id:s.id,number:s.scene_number,title:s.title,description:s.description||''});}}}}
      const localChars=state.characters;const cloudChars=(cRes.data||[]).map(c=>({id:c.id,projectId:c.project_id||'',name:c.name,description:c.description||'',abilities:c.abilities||'',notes:c.continuity_notes||'',extracted:c.extracted_text||'',imageName:c.reference_storage_path||'',createdAt:c.created_at}));
      const charMap=new Map([...localChars.map(c=>[c.id,c]),...cloudChars.map(c=>[c.id,{...(localChars.find(x=>x.id===c.id)||{}),...c}])]);state.characters=[...charMap.values()];
      const cloudAssets=(aRes.data||[]).map(a=>({id:a.id,name:a.name,kind:a.kind,mediaId:null,storagePath:a.storage_path,remote:true,type:a.content_type||'',size:a.size_bytes||0,createdAt:a.created_at,projectId:a.project_id||''}));
      const assetMap=new Map([...state.assets.map(a=>[a.id,a]),...cloudAssets.map(a=>[a.id,{...(state.assets.find(x=>x.id===a.id)||{}),...a}])]);state.assets=[...assetMap.values()];
      const cloudTasks=(jRes.data||[]).map(j=>({id:j.id,title:j.metadata?.title||j.prompt.slice(0,54),prompt:j.prompt,style:j.metadata?.style||'',ratio:j.metadata?.ratio||'16:9',duration:j.metadata?.duration||5,projectId:j.project_id||null,status:j.status,createdAt:j.created_at}));
      const localTasks=state.tasks;const taskMap=new Map([...localTasks.map(x=>[x.id,x]),...cloudTasks.map(x=>[x.id,{...(localTasks.find(y=>y.id===x.id)||{}),...x}])]);state.tasks=[...taskMap.values()];
      // Push local-only metadata to the signed-in user's cloud; do not automatically upload old large media files.
      const cloudProjectIds=new Set((pRes.data||[]).map(p=>p.id));
      for(const p of localProjects){if(!cloudProjectIds.has(p.id)){await syncProject(p);for(const ep of p.episodes||[])await syncEpisode(p,ep);}}
      const cloudCharacterIds=new Set((cRes.data||[]).map(c=>c.id));
      for(const c of localChars){if(!cloudCharacterIds.has(c.id))await syncCharacter(c);}
      const cloudTaskIds=new Set((jRes.data||[]).map(j=>j.id));
      for(const task of localTasks){if(!cloudTaskIds.has(task.id))await syncTask(task);}
      persist();renderAll();setConnection(true);
    }catch(e){console.warn('Cloud load failed',e);setConnection(false);}
  }
  async function cloudUpsert(table, payload) {
    if(!supabaseClient||!currentUser)return false;
    const row={...payload,user_id:currentUser.id};
    const {error}=await supabaseClient.from(table).upsert(row,{onConflict:'id'});
    if(error){console.warn(`Cloud save failed for ${table}`,error);toast(`${t('localOnly')} (${error.message})`);return false;}return true;
  }
  async function syncProject(p){return cloudUpsert('projects',{id:p.id,title:p.title,description:p.description,project_type:p.type,status:p.status,metadata:{},updated_at:new Date().toISOString()});}
  async function syncCharacter(c){return cloudUpsert('characters',{id:c.id,project_id:c.projectId||null,name:c.name,description:c.description,abilities:c.abilities,continuity_notes:c.notes,extracted_text:c.extracted,reference_storage_path:c.storagePath||null});}
  async function syncEpisode(project,ep){await cloudUpsert('episodes',{id:ep.id,project_id:project.id,episode_number:ep.number,title:ep.title,synopsis:ep.synopsis,status:'planning'});for(const sc of ep.scenes||[])await cloudUpsert('scenes',{id:sc.id,episode_id:ep.id,scene_number:sc.number,title:sc.title,description:sc.description,continuity_notes:''});}
  async function syncTask(task){return cloudUpsert('generation_jobs',{id:task.id,project_id:task.projectId||null,prompt:task.prompt,provider:'external-free-provider',status:'saved_prompt',progress:0,metadata:{title:task.title,style:task.style,ratio:task.ratio,duration:task.duration}});}
  async function uploadAssetCloud(asset,file){
    if(!supabaseClient||!currentUser||!file)return false;
    try{const clean=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`${currentUser.id}/${asset.id}-${clean}`;const {error:upErr}=await supabaseClient.storage.from('studio-assets').upload(path,file,{upsert:true,contentType:file.type||'application/octet-stream'});if(upErr)throw upErr;asset.storagePath=path;await cloudUpsert('media_assets',{id:asset.id,project_id:asset.projectId||null,kind:asset.kind,name:asset.name,storage_path:path,content_type:file.type||null,size_bytes:file.size,metadata:{}});persist();return true;}catch(e){toast(`تعذر رفع الملف سحابياً: ${e.message||e}`);return false;}
  }

  function applyLanguage() {
    document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';document.title=language==='ar'?'استوديو الإنتاج بالذكاء الاصطناعي':'AI Film Production Studio';localStorage.setItem('studio-lang',language);
    document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n; if(strings[language][key])el.textContent=strings[language][key];});
    document.querySelectorAll('[placeholder]').forEach(el=>{const key=el.dataset.placeholderI18n;if(key&&strings[language][key])el.placeholder=strings[language][key];});
    $('pageTitle').textContent=t(({home:'navHome',video:'navVideo',series:'navSeries',characters:'navCharacters',assembly:'navAssembly',library:'navLibrary',settings:'navSettings'})[currentView]||'navHome');
    $('backButton').title=t('back');syncBadge();renderAll();
  }
  function goView(view, push=true) {
    if(!$(`view-${view}`))view='home';
    if(push&&currentView!==view)historyStack.push(currentView);
    currentView=view;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));
    document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
    $('pageTitle').textContent=t(({home:'navHome',video:'navVideo',series:'navSeries',characters:'navCharacters',assembly:'navAssembly',library:'navLibrary',settings:'navSettings'})[view]||'navHome');
    $('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});if(view==='series')renderProjects();if(view==='library')renderLibrary();
  }
  function goBack(){if(historyStack.length){const prev=historyStack.pop();goView(prev,false);}else goView('home',false);}
  function updateStats(){if(!$('statProjects'))return;$('statProjects').textContent=state.projects.length;$('statCharacters').textContent=state.characters.length;$('statAssets').textContent=state.assets.length;$('statJobs').textContent=state.tasks.length;}
  function projectStatusLabel(status){return t(({planning:'statusPlanning',production:'statusProduction',complete:'statusComplete'})[status]||'statusPlanning');}
  function renderHome(){
    const root=$('recentProjects');if(!root)return;
    if(!state.projects.length){root.innerHTML=`<div class="empty-state"><span>✦</span><strong>${esc(t('noProjects'))}</strong><p>${esc(t('makeFirstProject'))}</p></div>`;return;}
    root.innerHTML=state.projects.slice().sort((a,b)=>new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt)).slice(0,4).map(p=>`<article class="project-row"><div class="project-row-main"><div class="project-thumb">${p.type==='film'?'▣':'▤'}</div><div><h3>${esc(p.title)}</h3><p>${esc(p.description||t('noText'))}</p></div></div><div class="row-actions"><span class="tag">${esc(projectStatusLabel(p.status))}</span><button class="mini-button" data-open-project="${p.id}">${esc(t('open'))}</button></div></article>`).join('');
  }
  function renderVideoSelect(){const sel=$('videoProject');if(!sel)return;const current=sel.value;sel.innerHTML=`<option value="">${esc(t('noProject'))}</option>`+state.projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('');if([...sel.options].some(o=>o.value===current))sel.value=current;}
