  function addProject(e){e.preventDefault();const title=$('projectTitle').value.trim();if(!title){toast(t('nameRequired'));return;}const now=new Date().toISOString();const existing=editingProjectId?state.projects.find(p=>p.id===editingProjectId):null;const project={...(existing||{}),id:existing?.id||makeId(),title,description:$('projectDescription').value.trim(),type:$('projectType').value,status:$('projectStatus').value,createdAt:existing?.createdAt||now,updatedAt:now,episodes:existing?.episodes||[]};if(existing)state.projects=state.projects.map(p=>p.id===project.id?project:p);else state.projects.push(project);selectedProjectId=project.id;editingProjectId=null;persist();syncProject(project);$('projectForm').reset();$('projectForm').querySelector('[type=submit]').textContent=t('createProject');renderAll();toast(t('projectCreated'));}
