  async function addCharacter(e){e.preventDefault();const name=$('characterName').value.trim();if(!name){toast(t('nameRequired'));return;}const existing=editingCharacterId?state.characters.find(x=>x.id===editingCharacterId):null;const c={...(existing||{}),id:existing?.id||makeId(),projectId:existing?.projectId||'',name,description:$('characterDescription').value.trim(),abilities:$('characterAbilities').value.trim(),notes:$('characterNotes').value.trim(),extracted:$('characterExtracted').value.trim(),imageName:pendingCharacterFile?.name||existing?.imageName||'',mediaId:existing?.mediaId||null,createdAt:existing?.createdAt||new Date().toISOString()};if(pendingCharacterFile){try{const oldMediaId=c.mediaId;c.mediaId=makeId();await putMedia(c.mediaId,pendingCharacterFile);if(oldMediaId)await deleteMedia(oldMediaId);}catch(err){console.warn(err);toast(t('localFileLimit'));return;}}
    if(existing){state.characters=state.characters.map(x=>x.id===c.id?c:x);}else state.characters.push(c);persist();await syncCharacter(c);$('characterForm').reset();pendingCharacterFile=null;editingCharacterId=null;$('saveCharacter').textContent=t('saveCharacter');if(previewCharacterUrl){URL.revokeObjectURL(previewCharacterUrl);previewCharacterUrl=null;}$('characterPreview').innerHTML=`<span>♙</span><small>${esc(t('noReference'))}</small>`;$('characterExtracted').value='';renderCharacters();toast(t('characterSaved'));}
  async function saveVideoUpload(){if(!pendingVideoFile){toast(t('videoRequired'));return;}const asset={id:makeId(),name:$('assetTitle').value.trim()||pendingVideoFile.name,kind:'video',mediaId:makeId(),size:pendingVideoFile.size,type:pendingVideoFile.type,projectId:$('videoProject').value||'',createdAt:new Date().toISOString()};try{await putMedia(asset.mediaId,pendingVideoFile);}catch(err){toast(t('localFileLimit'));return;}state.assets.push(asset);persist();if(currentUser)await uploadAssetCloud(asset,pendingVideoFile);pendingVideoFile=null;$('videoUpload').value='';$('assetTitle').value='';if(previewVideoUrl){URL.revokeObjectURL(previewVideoUrl);previewVideoUrl=null;}$('videoPreview').innerHTML=`<div class="preview-placeholder">▶</div><span>${esc(t('noPreview'))}</span>`;renderAll();toast(t('fileSaved'));}
  async function addAssemblyFiles(files){for(const file of files){const kind=file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':file.type.startsWith('image/')?'image':'document';const asset={id:makeId(),name:file.name,kind,mediaId:makeId(),type:file.type,size:file.size,createdAt:new Date().toISOString()};try{await putMedia(asset.mediaId,file);state.assets.push(asset);if(currentUser)await uploadAssetCloud(asset,file);}catch(e){toast(t('localFileLimit'));}}persist();renderAll();toast(t('clipAdded'));}
  async function mergeAssemblyVideos(){
    const btn=$('mergeClips'),status=$('assemblyEngineStatus'),progress=$('assemblyProgress'),output=$('assemblyOutput');
    const candidates=state.assets.filter(a=>a.kind==='video'&&a.mediaId);
    if(candidates.length<2){setMessage('assemblyEngineStatus',t('assemblyNeedTwoVideos'),true);return;}
    if(!window.AssemblyEngineBridge?.mergeVideos){setMessage('assemblyEngineStatus',t('assemblyFailed')+' (assembly-engine.js did not load)',true);return;}
    btn.disabled=true;progress.classList.remove('hidden');progress.value=0;output.replaceChildren();setMessage('assemblyEngineStatus',t('ffmpegLoading'));
    try{
      const inputItems=[];
      for(const asset of candidates){
        const stored=await getMedia(asset.mediaId);
        if(!stored?.blob)continue;
        const file=new File([stored.blob],asset.name||stored.name||'clip.mp4',{type:stored.type||asset.type||'video/mp4',lastModified:Date.now()});
        inputItems.push({...asset,file});
      }
      if(inputItems.length<2)throw new Error(t('assemblyNeedTwoVideos'));
      let externalAudioFile=null;const selectedAudio=state.assets.find(a=>a.id===$('assemblyAudioTrack').value&&a.kind==='audio'&&a.mediaId);if(selectedAudio){const storedAudio=await getMedia(selectedAudio.mediaId);if(storedAudio?.blob)externalAudioFile=new File([storedAudio.blob],selectedAudio.name||storedAudio.name||'audio.mp3',{type:storedAudio.type||selectedAudio.type||'audio/mpeg',lastModified:Date.now()});}
      const result=await window.AssemblyEngineBridge.mergeVideos(inputItems,{format:$('exportFormat').value,quality:$('exportQuality').value,audioFile:externalAudioFile,audioOffsetSeconds:Math.max(0,Math.min(3600,Number($('audioOffset').value)||0))},info=>{
        const pct=Number.isFinite(info?.percent)?info.percent:0;progress.value=Math.max(0,Math.min(100,pct));
        const msg=info?.stage==='downloading'?t('ffmpegLoading'):info?.stage==='preparing'?t('assemblyPreparing'):info?.stage==='merging'?t('assemblyMerging'):info?.stage==='normalizing'?t('assemblyTranscoding'):info?.stage==='complete'?t('assemblySaved'):t('assemblyMerging');
        setMessage('assemblyEngineStatus',`${msg} ${pct?`(${pct}%)`:''}`.trim());
      },message=>{if(message&&/error|failed|invalid/i.test(message))console.debug('FFmpeg:',message);});
      const finalId=makeId(),mediaId=makeId();
      const finalFile=new File([result.blob],result.filename,{type:result.mime,lastModified:Date.now()});
      await putMedia(mediaId,finalFile);
      state.assets.push({id:finalId,name:result.filename,kind:'video',mediaId,type:result.mime,size:result.bytes,createdAt:new Date().toISOString(),source:'assembled'});
      persist();renderAll();
      if(assemblyDownloadUrl)URL.revokeObjectURL(assemblyDownloadUrl);
      assemblyDownloadUrl=URL.createObjectURL(result.blob);
      const video=document.createElement('video');video.controls=true;video.playsInline=true;video.src=assemblyDownloadUrl;video.className='assembly-output-video';video.setAttribute('aria-label',result.filename);
      const link=document.createElement('a');link.href=assemblyDownloadUrl;link.download=result.filename;link.textContent=`↓ ${t('downloadMerged')} (${formatSize(result.bytes)})`;link.className='external-link assembly-download';
      const note=document.createElement('p');note.className='fine-note';note.textContent=t('assemblySaved');
      output.append(video,link,note);setMessage('assemblyEngineStatus',t('assemblySaved'));progress.value=100;
    }catch(error){console.error(error);setMessage('assemblyEngineStatus',`${t('assemblyFailed')}\n${error?.message||String(error)}`,true);$('exportNotice').classList.remove('hidden');}
    finally{btn.disabled=false;}
  }

  async function runOCR(){if(!pendingCharacterFile){toast(t('ocrFailed'));return;}if(!window.Tesseract){toast(t('ocrMissing'));return;}setMessage('ocrStatus',t('ocrStarting'));$('runOcr').disabled=true;try{const result=await window.Tesseract.recognize(pendingCharacterFile,'ara+eng',{logger:m=>{if(m.status&&m.progress)setMessage('ocrStatus',`${t('ocrStarting')} ${Math.round(m.progress*100)}%`);}});$('characterExtracted').value=(result.data?.text||'').trim();setMessage('ocrStatus',t('ocrDone'));}catch(e){console.error(e);setMessage('ocrStatus',t('ocrFailed'),true);}finally{$('runOcr').disabled=false;}}
  async function localPlan(idea){const safe=idea.trim();return `${language==='ar'?'الفكرة الأساسية':'Core idea'}\n${safe}\n\n${language==='ar'?'الخط الدرامي':'Dramatic arc'}\n1. ${language==='ar'?'تقديم العالم والشخصية والهدف.':'Introduce the world, character and goal.'}\n2. ${language==='ar'?'حدث محفّز يجبر البطل على الاختيار.':'An inciting event forces a choice.'}\n3. ${language==='ar'?'عقبات متصاعدة تكشف حدود الشخصية.':'Escalating obstacles reveal the character’s limits.'}\n4. ${language==='ar'?'ذروة ناتجة عن قرارات الشخصيات.':'A climax caused by the characters’ decisions.'}\n5. ${language==='ar'?'نتيجة تفتح باباً للحلقة التالية.':'Consequences that open the next chapter.'}\n\n${language==='ar'?'قواعد الاستمرارية':'Continuity rules'}\n- ${language==='ar'?'لا تضف قدرة أو تحوّلاً غير مكتوب.':'Do not add an unwritten ability or transformation.'}\n- ${language==='ar'?'احتفظ بدوافع الشخصيات ومستوى قوتها.':'Preserve character motivations and power levels.'}\n- ${language==='ar'?'قسّم الأحداث إلى مشاهد قصيرة قابلة للإنتاج.':'Break events into short, production-ready scenes.'}\n\n${t('plannerLocal')}`;}
  async function planStory(){const idea=$('plannerIdea').value.trim();if(!idea){toast(t('nameRequired'));return;}const out=$('plannerResult');out.textContent=t('loading');if(supabaseClient&&currentUser){try{const cfg=window.STUDIO_CONFIG||{};const {data,error}=await supabaseClient.functions.invoke(cfg.plannerFunctionName||'story-planner',{body:{idea,language}});if(error)throw error;out.textContent=data?.text||data?.plan||JSON.stringify(data,null,2);return;}catch(e){console.warn(e);out.textContent=`${t('plannerFailed')}\n${e.message||e}`;return;}}out.textContent=await localPlan(idea);}
  async function testConnection(){const url=$('supabaseUrl').value.trim(),key=$('supabaseAnon').value.trim();if(!url||!key){setMessage('connectionMessage',t('needSetup'),true);return;}try{const client=window.supabase.createClient(url,key);const {error}=await client.auth.getSession();if(error)throw error;const {error:dbError}=await client.from('projects').select('id').limit(1);if(dbError)throw dbError;setMessage('connectionMessage',t('cloudOk'));}catch(e){setMessage('connectionMessage',`${t('cloudNo')}\n${e.message||e}`,true);}}
  function saveConnection(){const url=$('supabaseUrl').value.trim(),key=$('supabaseAnon').value.trim();if(url&&!/^https:\/\//.test(url)){setMessage('connectionMessage',t('cloudNo'),true);return;}window.STUDIO_CONFIG={...(window.STUDIO_CONFIG||{}),supabaseUrl:url,supabaseAnonKey:key};try{localStorage.setItem('studio-supabase-url',url);localStorage.setItem('studio-supabase-key',key);}catch{}setMessage('connectionMessage',t('keyStored'));initSupabase();}
  function loadConfigFields(){const cfg=window.STUDIO_CONFIG||{};const url=localStorage.getItem('studio-supabase-url')||cfg.supabaseUrl||'';const key=localStorage.getItem('studio-supabase-key')||cfg.supabaseAnonKey||'';$('supabaseUrl').value=url;$('supabaseAnon').value=key;if(url&&key){window.STUDIO_CONFIG={...cfg,supabaseUrl:url,supabaseAnonKey:key};initSupabase();}}
  function downloadBackup(){try{const backup={app:'AI Film Studio',version:1,exportedAt:new Date().toISOString(),data:state};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`ai-film-studio-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('backupDone'));}catch(e){toast(t('copyBackupError'));}}
  async function importBackup(file){try{const parsed=JSON.parse(await file.text());const incoming=parsed.data||parsed;if(!incoming||!Array.isArray(incoming.projects)||!Array.isArray(incoming.characters)||!Array.isArray(incoming.tasks))throw new Error('invalid');state={...defaultState,...incoming};persist();renderAll();toast(t('restoreDone'));}catch(e){toast(t('backupInvalid'));}}
  async function clearLocal(){if(!confirm(t('clearConfirm')))return;localStorage.removeItem(STORE_KEY);state=structuredClone(defaultState);try{const db=await openMediaDB();await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();}catch{}for(const url of blobUrls.values())URL.revokeObjectURL(url);blobUrls.clear();if(previewVideoUrl)URL.revokeObjectURL(previewVideoUrl);if(previewCharacterUrl)URL.revokeObjectURL(previewCharacterUrl);previewVideoUrl=previewCharacterUrl=null;pendingVideoFile=pendingCharacterFile=null;persist();renderAll();toast(t('clearWarning'));}
  async function openAsset(id){const asset=state.assets.find(a=>a.id===id);if(!asset)return;const url=asset.mediaId?await getMediaUrl(asset.mediaId):null;if(url){window.open(url,'_blank','noopener');return;}if(asset.storagePath&&supabaseClient){const {data,error}=await supabaseClient.storage.from('studio-assets').createSignedUrl(asset.storagePath,300);if(!error&&data?.signedUrl){window.open(data.signedUrl,'_blank','noopener');return;}}toast(t('projectMissing'));}
  async function deleteAsset(id){const asset=state.assets.find(a=>a.id===id);if(!asset||!confirm(t('deleteConfirm')))return;state.assets=state.assets.filter(a=>a.id!==id);persist();if(asset.mediaId)await deleteMedia(asset.mediaId);if(currentUser&&asset.storagePath){try{await supabaseClient.storage.from('studio-assets').remove([asset.storagePath]);await supabaseClient.from('media_assets').delete().eq('id',id);}catch{}}renderAll();}
  async function deleteCharacter(id){if(!confirm(t('deleteConfirm')))return;const c=state.characters.find(x=>x.id===id);state.characters=state.characters.filter(x=>x.id!==id);persist();if(c?.mediaId)await deleteMedia(c.mediaId);if(supabaseClient&&currentUser)await supabaseClient.from('characters').delete().eq('id',id);renderAll();}
  async function deleteProject(id){if(!confirm(t('deleteProject')+'?'))return;state.projects=state.projects.filter(x=>x.id!==id);if(selectedProjectId===id)selectedProjectId=state.projects[0]?.id||null;persist();if(supabaseClient&&currentUser)await supabaseClient.from('projects').delete().eq('id',id);renderAll();}
  function deleteEpisode(projectId,epId){const p=state.projects.find(x=>x.id===projectId);if(!p||!confirm(t('deleteConfirm')))return;p.episodes=(p.episodes||[]).filter(e=>e.id!==epId);persist();syncProject(p);renderProjects();}
  function deleteTask(id){state.tasks=state.tasks.filter(x=>x.id!==id);persist();if(supabaseClient&&currentUser)supabaseClient.from('generation_jobs').delete().eq('id',id).then(()=>{});renderTasks();}
  function moveAsset(id,direction){const relevant=state.assets.filter(a=>['video','audio'].includes(a.kind));const currentIndex=relevant.findIndex(a=>a.id===id);const nextIndex=currentIndex+(direction==='up'?-1:1);if(currentIndex<0||nextIndex<0||nextIndex>=relevant.length)return;const a=relevant[currentIndex],b=relevant[nextIndex];const idxA=state.assets.findIndex(x=>x.id===a.id),idxB=state.assets.findIndex(x=>x.id===b.id);[state.assets[idxA],state.assets[idxB]]=[state.assets[idxB],state.assets[idxA]];persist();renderAssembly();}

  // Event delegation: navigation and repeated item buttons.
  document.addEventListener('click',async e=>{
    const nav=e.target.closest('[data-view]');if(nav){goView(nav.dataset.view);return;}
    const go=e.target.closest('[data-go]');if(go){goView(go.dataset.go);return;}
    const openP=e.target.closest('[data-open-project]');if(openP){selectedProjectId=openP.dataset.openProject;goView('series');renderProjects();return;}
    const delP=e.target.closest('[data-delete-project]');if(delP){deleteProject(delP.dataset.deleteProject);return;}
    const editP=e.target.closest('[data-edit-project]');if(editP){editProject(editP.dataset.editProject);return;}
    const copyT=e.target.closest('[data-copy-task]');if(copyT){const task=state.tasks.find(x=>x.id===copyT.dataset.copyTask);if(task){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(task.prompt).then(()=>toast(t('copyPrompt'))).catch(()=>window.prompt(t('copyPrompt'),task.prompt));}else window.prompt(t('copyPrompt'),task.prompt);}return;}
    const delC=e.target.closest('[data-delete-character]');if(delC){deleteCharacter(delC.dataset.deleteCharacter);return;}
    const editC=e.target.closest('[data-edit-character]');if(editC){editCharacter(editC.dataset.editCharacter);return;}
    const delA=e.target.closest('[data-delete-asset]');if(delA){deleteAsset(delA.dataset.deleteAsset);return;}
    const openA=e.target.closest('[data-open-asset]');if(openA){openAsset(openA.dataset.openAsset);return;}
    const delT=e.target.closest('[data-delete-task]');if(delT){deleteTask(delT.dataset.deleteTask);return;}
    const delE=e.target.closest('[data-delete-episode]');if(delE){deleteEpisode(delE.dataset.projectId,delE.dataset.deleteEpisode);return;}
    const move=e.target.closest('[data-move-asset]');if(move){moveAsset(move.dataset.moveAsset,move.dataset.direction);return;}
  });
